//! `POST /v1/publishers/{id}/tokens`.

use registry_domain::{Scope, Timestamp};
use time::format_description::well_known::Rfc3339;

use crate::HttpError;

/// The scopes and optional expiry of a new token; the token itself is
/// generated by the API and shown once.
#[derive(Debug, Clone, PartialEq, Eq, serde::Deserialize, serde::Serialize)]
#[serde(deny_unknown_fields)]
pub struct IssueTokenRequest {
    /// The scopes.
    pub scopes: Vec<String>,
    /// When it expires, RFC 3339; never when absent.
    #[serde(default)]
    pub expires_at: Option<String>,
}

impl IssueTokenRequest {
    /// The validated scopes and expiry.
    pub fn into_parts(self) -> Result<(Vec<Scope>, Option<Timestamp>), HttpError> {
        let scopes = self.scopes.iter().map(|s| Scope::parse(s)).collect::<Result<Vec<_>, _>>()?;
        let expires_at = self
            .expires_at
            .as_deref()
            .map(|s| Timestamp::parse(s, &Rfc3339).map_err(|e| HttpError::BadRequest(format!("expires_at: {e}"))))
            .transpose()?;
        Ok((scopes, expires_at))
    }
}

#[cfg(test)]
mod tests {
    use super::IssueTokenRequest;

    #[test]
    fn validates() {
        let good = IssueTokenRequest { scopes: vec!["acme_*".into()], expires_at: Some("2027-01-01T00:00:00Z".into()) };
        let (scopes, expires) = good.into_parts().unwrap();
        assert_eq!((scopes.len(), expires.unwrap().year()), (1, 2027));
        assert!(IssueTokenRequest { scopes: vec!["Bad".into()], expires_at: None }.into_parts().is_err());
        assert!(IssueTokenRequest { scopes: vec![], expires_at: Some("tomorrow".into()) }.into_parts().is_err());
        assert!(serde_json::from_str::<IssueTokenRequest>("{\"scopes\":[\"a\"]}").unwrap().expires_at.is_none());
    }
}
